-			err := run(&buf, n, mode.asJSON)
+			err := run(&buf, n, mode.asJSON, false)
 			if err == nil {
 				t.Fatalf("run(%d, %s) succeeded, want error", n, mode.name)
 			}
diff --git a/main.go b/main.go
index 435e69a..2ea2e1c 100644
--- a/main.go
+++ b/main.go
@@ -1,7 +1,8 @@
 // Command gofib prints Fibonacci numbers, one per line, prefixed with
 // the index: "1: 1", "2: 1", "3: 2", ... By default it prints the first
-// 100; the -n flag changes how many are printed, and -json switches to
-// JSON Lines output.
+// 100; the -n flag changes how many are printed, -json switches to
+// JSON Lines output, and -pretty right-aligns text output into columns
+// sized to the largest index and value (it has no effect on -json).
 package main

 import (
@@ -33,19 +34,30 @@ func Fib(n int) *big.Int {
 }

 // run writes the first count Fibonacci numbers to w. In text mode each
-// line is "<index>: <value>"; in JSON mode each line is one JSON object
-// {"index": <int>, "fib": "<value>"} (JSON Lines). It returns an error
-// when count < 1.
-func run(w io.Writer, count int, asJSON bool) error {
+// line is "<index>: <value>"; with pretty, the index and value are
+// right-aligned in columns as wide as the largest of each — both occur
+// at count, since Fib is monotonic. In JSON mode each line is one JSON
+// object {"index": <int>, "fib": "<value>"} (JSON Lines); pretty has no
+// effect on JSON output. It returns an error when count < 1.
+func run(w io.Writer, count int, asJSON bool, pretty bool) error {
 	if count < 1 {
 		return fmt.Errorf("invalid value %d for flag -n: must be >= 1", count)
 	}
+	// Column widths for pretty text mode, derived from the largest
+	// index and value; zero when pretty does not apply.
+	idxW, valW := 0, 0
+	if pretty && !asJSON {
+		idxW = len(fmt.Sprint(count))
+		valW = len(Fib(count).String())
+	}
 	enc := json.NewEncoder(w)
 	for i := 1; i <= count; i++ {
 		if asJSON {
 			if err := enc.Encode(fibLine{Index: i, Fib: Fib(i).String()}); err != nil {
 				return err
 			}
+		} else if pretty {
+			fmt.Fprintf(w, "%*d: %*s\n", idxW, i, valW, Fib(i).String())
 		} else {
 			fmt.Fprintf(w, "%d: %v\n", i, Fib(i))
 		}
@@ -56,8 +68,9 @@ func run(w io.Writer, count int, asJSON bool) error {
 func main() {
 	n := flag.Int("n", defaultCount, "how many Fibonacci numbers to print (must be >= 1; default 100)")
 	asJSON := flag.Bool("json", false, "emit JSON Lines instead of text: one {\"index\": i, \"fib\": \"value\"} object per number")
+	pretty := flag.Bool("pretty", false, "right-align text output into columns sized to the largest index and value; affects text output only, not -json")
 	flag.Parse()
-	if err := run(os.Stdout, *n, *asJSON); err != nil {
+	if err := run(os.Stdout, *n, *asJSON, *pretty); err != nil {
 		fmt.Fprintln(os.Stderr, err)
 		os.Exit(1)
 	}

